getStatusbarColumn(rawPosition) {
        if (!this.tb) {
            return rawPosition.column;
        }
        const position = this.tb.model.validatePosition(rawPosition);
        const tabSize = this.tb.model.getOptions().tabSize;
        return $lF.toStatusbarColumn(this.tb.model.getLineContent(position.lineNumber), position.column, tabSize);
    }
